// bfsFrom returns the sum of distances from one node, in O(n). Used as a cheap
// oracle on the big trees: doing it for every node is the O(n^2) approach the
// sizes below rule out.
func bfsFrom(n int, adj [][]int32, src int) int {
	dist := make([]int32, n)
	for i := range dist {
		dist[i] = -1
	}
	dist[src] = 0
	q := make([]int32, 1, n)
	q[0] = int32(src)
	total := 0
	for i := 0; i < len(q); i++ {
		u := q[i]
		for _, v := range adj[u] {
			if dist[v] < 0 {
				dist[v] = dist[u] + 1
				total += int(dist[v])
				q = append(q, v)
			}
		}
	}
	return total
}

func adjacency(n int, edges [][]int) [][]int32 {
	deg := make([]int, n)
	for _, e := range edges {
		deg[e[0]]++
		deg[e[1]]++
	}
	adj := make([][]int32, n)
	for i := range adj {
		adj[i] = make([]int32, 0, deg[i])
	}
	for _, e := range edges {
		adj[e[0]] = append(adj[e[0]], int32(e[1]))
		adj[e[1]] = append(adj[e[1]], int32(e[0]))
	}
	return adj
}

func TestSumOfDistancesSmallCases(t *testing.T) {
	if got := sumOfDistances(1, [][]int{}); len(got) != 1 || got[0] != 0 {
		t.Fatalf("single node: got %v, want [0]", got)
	}
	if got := sumOfDistances(2, [][]int{{0, 1}}); len(got) != 2 || got[0] != 1 || got[1] != 1 {
		t.Fatalf("two nodes: got %v, want [1 1]", got)
	}
	// LeetCode 834's example tree.
	edges := [][]int{{0, 1}, {0, 2}, {2, 3}, {2, 4}, {2, 5}}
	want := []int{8, 12, 6, 10, 10, 10}
	got := sumOfDistances(6, edges)
	if len(got) != len(want) {
		t.Fatalf("got %d values, want %d", len(got), len(want))
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("sumOfDistances = %v, want %v", got, want)
		}
	}
}

func TestSumOfDistancesMatchesBruteForce(t *testing.T) {
	rng := rand.New(rand.NewSource(31))
	for trial := 0; trial < 300; trial++ {
		n := 1 + rng.Intn(12)
		edges := make([][]int, 0, n-1)
		for v := 1; v < n; v++ {
			edges = append(edges, []int{rng.Intn(v), v})
		}
		rng.Shuffle(len(edges), func(i, j int) { edges[i], edges[j] = edges[j], edges[i] })
		adj := adjacency(n, edges)
		got := sumOfDistances(n, edges)
		if len(got) != n {
			t.Fatalf("got %d values, want %d", len(got), n)
		}
		for v := 0; v < n; v++ {
			if want := bfsFrom(n, adj, v); got[v] != want {
				t.Fatalf("n=%d edges=%v: node %d = %d, want %d", n, edges, v, got[v], want)
			}
		}
	}
}

// TestSumOfDistancesOnPath uses a 200000-node path, where the answer is known
// in closed form and one BFS per node would take minutes.
func TestSumOfDistancesOnPath(t *testing.T) {
	const n = 200000
	edges := make([][]int, 0, n-1)
	for v := 1; v < n; v++ {
		edges = append(edges, []int{v - 1, v})
	}
	got := sumOfDistances(n, edges)
	if len(got) != n {
		t.Fatalf("got %d values, want %d", len(got), n)
	}
	for _, i := range []int{0, 1, 7919, n / 2, n - 2, n - 1} {
		left, right := i, n-1-i
		want := left*(left+1)/2 + right*(right+1)/2
		if got[i] != want {
			t.Fatalf("path node %d = %d, want %d", i, got[i], want)
		}
	}
}

// TestSumOfDistancesOnLargeRandomTree checks three entries against a
// single-source BFS and the whole vector against the edge-split identity:
// summing over nodes counts every ordered pair once, and an edge separating a
// nodes from n-a contributes a*(n-a) to each direction.
func TestSumOfDistancesOnLargeRandomTree(t *testing.T) {
	const n = 200000
	rng := rand.New(rand.NewSource(2718))
	edges := make([][]int, 0, n-1)
	for v := 1; v < n; v++ {
		// A parent drawn from a window keeps the tree deep rather than starlike.
		lo := v - 1 - rng.Intn(40)
		if lo < 0 {
			lo = 0
		}
		edges = append(edges, []int{lo, v})
	}
	rng.Shuffle(len(edges), func(i, j int) { edges[i], edges[j] = edges[j], edges[i] })

	got := sumOfDistances(n, edges)
	if len(got) != n {
		t.Fatalf("got %d values, want %d", len(got), n)
	}
	adj := adjacency(n, edges)
	for _, v := range []int{0, 1, n / 3, n - 1} {
		if want := bfsFrom(n, adj, v); got[v] != want {
			t.Fatalf("node %d = %d, want %d", v, got[v], want)
		}
	}

	// Subtree sizes by processing a BFS order backwards.
	parent := make([]int32, n)
	parent[0] = -1
	order := make([]int32, 1, n)
	seen := make([]bool, n)
	seen[0] = true
	for i := 0; i < len(order); i++ {
		u := order[i]
		for _, v := range adj[u] {
			if !seen[v] {
				seen[v] = true
				parent[v] = u
				order = append(order, v)
			}
		}
	}
	size := make([]int, n)
	total := 0
	for i := len(order) - 1; i >= 1; i-- {
		v := order[i]
		size[v]++
		size[parent[v]] += size[v]
		total += 2 * size[v] * (n - size[v])
	}
	sum := 0
	for _, v := range got {
		sum += v
	}
	if sum != total {
		t.Fatalf("total over all nodes = %d, want %d", sum, total)
	}
}"
