// countNoAdjacentEqual returns how many integers in [1, n] have no two adjacent
// equal digits, with n given as a decimal string.
func countNoAdjacentEqual(n string) int {
	// dp[d] = count of ways so far whose last placed digit is d; index 10 means
	// nothing has been placed yet (the number is still all leading zeros).
	var dp [11]int
	dp[10] = 1
	total := 0
	for i := 0; i < len(n); i++ {
		limit := int(n[i] - '0')
		var next [11]int
		// Free positions: every earlier prefix that was already below the bound.
		for last := 0; last <= 10; last++ {
			if dp[last] == 0 {
				continue
			}
			for d := 0; d <= 9; d++ {
				if d == last {
					continue
				}
				if last == 10 && d == 0 {
					next[10] += dp[last]
					continue
				}
				next[d] += dp[last]
			}
		}
		// The tight prefix contributes separately: it may place any digit below
		// the bound (becoming free) or the bound itself (staying tight).
		_ = limit
		dp = next
		total = total
	}
	_ = total
	return 0
}
EOF
