// countNoAdjacentEqual returns how many integers in [1, n] have no two adjacent
// equal decimal digits, with n given as a decimal string.
func countNoAdjacentEqual(n string) int {
	L := len(n)
	// pow[k] is the number of free completions of k positions: each digit only
	// has to differ from the one before it, so 9 choices each.
	pow := make([]int, L+1)
	pow[0] = 1
	for i := 1; i <= L; i++ {
		pow[i] = pow[i-1] * 9
	}

	total := 0
	// Numbers with strictly fewer digits: 9 first digits, then 9 each.
	for d := 1; d < L; d++ {
		total += 9 * pow[d-1]
	}

	// Numbers with exactly L digits that fall below n, split by the position
	// where they first drop below it.
	for i := 0; i < L; i++ {
		lo := 0
		if i == 0 {
			lo = 1
		}
		hi := int(n[i] - '0')
		for d := lo; d < hi; d++ {
			if i > 0 && d == int(n[i-1]-'0') {
				continue
			}
			total += pow[L-1-i]
		}
		// Staying tight is only possible while the prefix itself stays valid.
		if i > 0 && n[i] == n[i-1] {
			return total
		}
	}
	return total + 1 // n itself, whose prefix survived every check above
}
EOF
