package main

// naive recursive digit DP with no "started" flag: leading zeros count as a
// real digit 0, which is the classic mistake.
func countNoAdjacentEqual(n string) int {
	L := len(n)
	memo := map[[3]int]int{}
	var rec func(pos, last int, tight bool) int
	rec = func(pos, last int, tight bool) int {
		if pos == L {
			return 1
		}
		ti := 0
		if tight {
			ti = 1
		}
		key := [3]int{pos, last, ti}
		if v, ok := memo[key]; ok && !tight {
			return v
		}
		hi := 9
		if tight {
			hi = int(n[pos] - '0')
		}
		total := 0
		for d := 0; d <= hi; d++ {
			if d == last {
				continue
			}
			total += rec(pos+1, d, tight && d == hi)
		}
		if !tight {
			memo[key] = total
		}
		return total
	}
	return rec(0, -1, true) - 1
}
