package main

// firstPlayerWins reports whether the player to move wins the subtraction game
// under optimal play from both sides.
func firstPlayerWins(piles []int, moves []int) bool {
	max := 0
	for _, p := range piles {
		if p > max {
			max = p
		}
	}
	g := make([]int, max+1)
	seen := make([]int, len(moves)+2)
	for i := range seen {
		seen[i] = -1
	}
	for n := 1; n <= max; n++ {
		for _, m := range moves {
			if m <= n && g[n-m] < len(seen) {
				seen[g[n-m]] = n
			}
		}
		mex := 0
		for seen[mex] == n {
			mex++
		}
		g[n] = mex
	}
	x := 0
	for _, p := range piles {
		x ^= g[p]
	}
	return x != 0
}
EOF
