package main

import (
	"math/rand"
	"testing"
)

// bruteWins searches the whole joint state space: exponential in the number of
// piles, so it is only usable on tiny games.
func bruteWins(piles []int, moves []int) bool {
	memo := map[string]bool{}
	var rec func(st []int) bool
	rec = func(st []int) bool {
		key := ""
		for _, v := range st {
			key += string(rune('a' + v))
		}
		if v, ok := memo[key]; ok {
			return v
		}
		win := false
		for i, p := range st {
			for _, m := range moves {
				if m <= p {
					st[i] = p - m
					if !rec(st) {
						win = true
					}
					st[i] = p
					if win {
						break
					}
				}
			}
			if win {
				break
			}
		}
		memo[key] = win
		return win
	}
	cp := append([]int(nil), piles...)
	return rec(cp)
}

func TestAgainstBrute(t *testing.T) {
	rng := rand.New(rand.NewSource(7))
	for trial := 0; trial < 400; trial++ {
		k := 1 + rng.Intn(3)
		piles := make([]int, k)
		for i := range piles {
