		nm := 1 + rng.Intn(4)
		set := map[int]bool{}
		for len(set) < nm {
			set[1+rng.Intn(5)] = true
		}
		moves := []int{}
		for m := range set {
			moves = append(moves, m)
		}
		got := firstPlayerWins(piles, moves)
		want := bruteWins(piles, moves)
		if got != want {
			t.Fatalf("piles=%v moves=%v: got %v want %v", piles, moves, got, want)
		}
	}
