package main

import "sort"

// countSubsetsAtMost returns how many of the 2^len(nums) subsets have a sum of
// at most target. The empty subset counts, so the answer is at least 1 for a
// non-negative target.
func countSubsetsAtMost(nums []int, target int) int {
	if target < 0 {
		return 0
	}
	half := len(nums) / 2
	a := subsetSums(nums[:half])
	b := subsetSums(nums[half:])
	sort.Ints(a)
	sort.Ints(b)
	total := 0
	j := len(b) - 1
	for _, v := range a {
		for j >= 0 && b[j] > target-v {
			j--
		}
		if j < 0 {
			break
		}
		total += j + 1
	}
	return total
}

func subsetSums(xs []int) []int {
	out := make([]int, 1, 1<<len(xs))
	for _, x := range xs {
