package main

import (
	"math/rand"
	"testing"
)

func brute(nums []int, target int) int {
	c := 0
	for mask := 0; mask < 1<<len(nums); mask++ {
		s := 0
		for i := range nums {
			if mask&(1<<i) != 0 {
				s += nums[i]
			}
		}
		if s <= target {
			c++
		}
	}
	return c
}

func TestBrute(t *testing.T) {
	rng := rand.New(rand.NewSource(5))
	for trial := 0; trial < 200; trial++ {
		n := rng.Intn(15)
		nums := make([]int, n)
		tot := 0
		for i := range nums {
			nums[i] = rng.Intn(50)
			tot += nums[i]
		}
		tg := rng.Intn(tot + 2)
		if got, want := countSubsetsAtMost(nums, tg), brute(nums, tg); got != want {
			t.Fatalf("nums=%v t=%d got %d want %d", nums, tg, got, want)
		}
	}
}

func TestPowersOfTwo(t *testing.T) {
