	for i := range nums {
		nums[i] = 1 << i
	}
	for _, tg := range []int{0, 1, 12345678901, (1 << 40) - 1} {
		if got := countSubsetsAtMost(nums, tg); got != tg+1 {
			t.Fatalf("target %d: got %d want %d", tg, got, tg+1)
		}
	}
