// the large tests below exist: it cannot be scaled.
func bruteWins(piles []int, moves []int) bool {
	memo := map[string]bool{}
	st := append([]int(nil), piles...)
	var rec func() bool
	rec = func() bool {
		key := make([]byte, len(st))
		for i, v := range st {
			key[i] = byte(v)
		}
		if v, ok := memo[string(key)]; ok {
			return v
		}
		win := false
		for i := range st {
			for _, m := range moves {
				if m <= st[i] {
					st[i] -= m
					lost := !rec()
					st[i] += m
					if lost {
						win = true
						break
					}
				}
			}
			if win {
				break
			}
		}
		memo[string(key)] = win
		return win
	}
	return rec()
}

func TestFirstPlayerWinsSmallCases(t *testing.T) {
	if firstPlayerWins([]int{0, 0}, []int{1, 2}) {
		t.Fatal("no stones left: the player to move has lost")
	}
	if !firstPlayerWins([]int{3}, []int{1, 2}) {
		t.Fatal("one pile of 3 with moves 1,2: taking 2 leaves a loss for the opponent")
	}
	if firstPlayerWins([]int{4, 4}, []int{1, 2, 3}) {
		t.Fatal("two equal piles under a symmetric move set is a loss")
	}
}

// TestFirstPlayerWinsAgainstBruteForce compares against the full game search on
// games small enough to enumerate. This is what separates a correct combination
// of the piles from a plausible-looking one.
func TestFirstPlayerWinsAgainstBruteForce(t *testing.T) {
	rng := rand.New(rand.NewSource(20260907))
	for trial := 0; trial < 400; trial++ {
		piles := make([]int, 1+rng.Intn(4))
		for i := range piles {
			piles[i] = rng.Intn(9)
		}
		set := map[int]bool{}
		for want := 1 + rng.Intn(4); len(set) < want; {
			set[1+rng.Intn(5)] = true
		}
		moves := make([]int, 0, len(set))
		for m := range set {
			moves = append(moves, m)
		}
		got := firstPlayerWins(piles, moves)
		if want := bruteWins(piles, moves); got != want {
			t.Fatalf("piles=%v moves=%v: got %v, want %v", piles, moves, got, want)
		}
	}
}

// TestFirstPlayerWinsOnLargePiles uses moves 1..7, where a pile of n is worth
// n mod 8, so the answer is known without any search. 200000 piles of up to a
// million stones is far past what enumerating game states can reach.
func TestFirstPlayerWinsOnLargePiles(t *testing.T) {
	moves := []int{1, 2, 3, 4, 5, 6, 7}
	rng := rand.New(rand.NewSource(8191))
	piles := make([]int, 200000)
	x := 0
	for i := range piles {
		piles[i] = rng.Intn(1000001)
		x ^= piles[i] % 8
	}
	if got := firstPlayerWins(piles, moves); got != (x != 0) {
		t.Fatalf("large game: got %v, want %v", got, x != 0)
	}
	// A single pile that is a multiple of 8 is a loss however big it is.
	if firstPlayerWins([]int{999992}, moves) {
		t.Fatal("a pile of 999992 with moves 1..7 is a loss for the player to move")
	}
}

// TestFirstPlayerWinsOnSparseMoveSet keeps a large pile with a move set that has
// gaps, so the per-pile values have to be computed rather than reduced modulo
// anything. Every prefix of the sequence is checked against the small search.
func TestFirstPlayerWinsOnSparseMoveSet(t *testing.T) {
	moves := []int{2, 3, 7}
	for n := 0; n <= 40; n++ {
		if got, want := firstPlayerWins([]int{n}, moves), bruteWins([]int{n}, moves); got != want {
			t.Fatalf("single pile %d with moves %v: got %v, want %v", n, moves, got, want)
		}
	}
	piles := make([]int, 100000)
	for i := range piles {
		piles[i] = 300000 + i
	}
	// Every value appears with both parities of its class, and the whole
	// sequence is symmetric enough that the answer is stable; just check it
	// runs in time and agrees with itself when the order is reversed.
	first := firstPlayerWins(piles, moves)
	for i, j := 0, len(piles)-1; i < j; i, j = i+1, j-1 {
		piles[i], piles[j] = piles[j], piles[i]
	}
	if second := firstPlayerWins(piles, moves); second != first {
		t.Fatal("the answer must not depend on the order of the piles")
	}
}
